#!/usr/bin/env bash
# Generate docker-compose.employees.yml from employees.json. One service
# per employee. Run before `docker compose up` (bin/up.sh does it for you).
#
# Idempotent: rewrites the same file every time. Safe to commit the
# generated file or re-generate from CI; either way the source of truth
# is employees.json.
set -euo pipefail

DEV_ENV_DIR="$(CDPATH= cd -- "$(dirname -- "$0")/.." && pwd)"
cd "$DEV_ENV_DIR"

CONFIG="${EMPLOYEES_CONFIG:-$DEV_ENV_DIR/employees.json}"
OUT="${COMPOSE_OUT:-$DEV_ENV_DIR/docker-compose.employees.yml}"
ENV_DIR="$DEV_ENV_DIR/employees"

if [ ! -r "$CONFIG" ]; then
    cat >&2 <<EOF
ERROR: $CONFIG missing.
  cp employees.json.example employees.json
  ${EDITOR:-vim} employees.json
EOF
    exit 2
fi
if ! jq -e . "$CONFIG" >/dev/null 2>&1; then
    echo "ERROR: $CONFIG is not valid JSON" >&2
    exit 3
fi

mkdir -p "$ENV_DIR"

EMPLOYEES=$(jq -r '.employees | keys[]' "$CONFIG")
if [ -z "$EMPLOYEES" ]; then
    echo "ERROR: $CONFIG has no employees" >&2
    exit 4
fi

# Header.
{
    cat <<'HDR'
# GENERATED by bin/render-employees-compose.sh — do not edit by hand.
# Source of truth: employees.json. Re-generate with:
#   ./bin/render-employees-compose.sh
#
# Loaded as an overlay alongside the workstation compose file. Both are
# named in COMPOSE_FILE in .env, so a plain `docker compose ...` in this
# directory picks them up; bin/up.sh renders this file first.

services:
HDR
} > "$OUT"

# One block per employee.
while IFS= read -r LOGIN; do
    [ -z "$LOGIN" ] && continue

    HOST=$(jq -r --arg l "$LOGIN" '.employees[$l].host // empty' "$CONFIG")
    PORT=$(jq -r --arg l "$LOGIN" '.employees[$l].port // 22' "$CONFIG")
    SSH_HOST_PORT=$(jq -r --arg l "$LOGIN" '.employees[$l].sshHostPort // empty' "$CONFIG")
    GH_LOGIN=$(jq -r --arg l "$LOGIN" '.employees[$l].githubLogin // empty' "$CONFIG")

    if [ -z "$HOST" ]; then
        echo "ERROR: employees.$LOGIN.host is required" >&2
        exit 5
    fi

    SVC="${LOGIN}-agent"
    CONTAINER="onym-${LOGIN}-agent"
    HOME_VOL="${LOGIN}-home"
    CACHE_VOL="${LOGIN}-cache"
    ENV_FILE="./employees/${LOGIN}.env"

    {
        cat <<EMP
  ${SVC}:
    image: onym-n8n/dev-env-agent:latest
    platform: linux/arm64
    container_name: ${CONTAINER}
    hostname: ${HOST}
    build:
      context: .
      dockerfile: Dockerfile.agent
      platforms:
        - linux/arm64
    tmpfs:
      - /run
      - /run/sshd
    cap_drop: [ALL]
    cap_add:
      - CHOWN
      - SETUID
      - SETGID
      - DAC_OVERRIDE
      - FOWNER
      - NET_BIND_SERVICE
      - SYS_CHROOT
      - AUDIT_WRITE
    security_opt:
      - no-new-privileges:true
    restart: unless-stopped
    environment:
      ROLE: employee
      EMPLOYEE_LOGIN: "${LOGIN}"
      EMPLOYEE_GITHUB_LOGIN: "${GH_LOGIN}"
      NODE_OPTIONS: "--max-old-space-size=6144"
      GRADLE_OPTS: "-Xmx4g -Dorg.gradle.jvmargs=-Xmx4g"
    env_file:
      - path: ${ENV_FILE}
        required: false
EMP

        if [ -n "$SSH_HOST_PORT" ]; then
            cat <<PORTS
    ports:
      - "127.0.0.1:${SSH_HOST_PORT}:22"
PORTS
        fi

        cat <<TAIL
    volumes:
      - ${HOME_VOL}:/home/agent
      - ${CACHE_VOL}:/cache
    networks:
      - employees-net
    mem_limit: 8g
    memswap_limit: 12g
    cpus: 4.0

TAIL
    } >> "$OUT"

    # Seed the env file from employee.env.example if missing (gitignored
    # real file). Re-running the generator will NOT overwrite an
    # existing employees/<login>.env so your filled-in tokens are safe.
    if [ ! -f "${ENV_DIR}/${LOGIN}.env" ]; then
        TEMPLATE="${DEV_ENV_DIR}/employee.env.example"
        if [ -r "$TEMPLATE" ]; then
            # Pure-bash substitution so we don't depend on gettext/envsubst
            # being installed on macOS. Strip the renderer-facing doc
            # header (everything before `# === TEMPLATE BEGIN ===`),
            # then replace __LOGIN__ / __GH_LOGIN__ literally; ${...}
            # shell expressions stay untouched.
            CONTENT=$(awk '/^# === TEMPLATE BEGIN ===/{found=1; next} found' "$TEMPLATE")
            CONTENT="${CONTENT//__LOGIN__/$LOGIN}"
            CONTENT="${CONTENT//__GH_LOGIN__/$GH_LOGIN}"
            printf '%s\n' "$CONTENT" > "${ENV_DIR}/${LOGIN}.env"
        else
            # Fallback if employee.env.example was deleted — keeps the
            # renderer self-contained.
            cat > "${ENV_DIR}/${LOGIN}.env" <<ENV
GITHUB_TOKEN=ghs_REPLACE_ME
ANTHROPIC_API_KEY=sk-ant-REPLACE_ME
GIT_COMMITTER_NAME=${GH_LOGIN:-${LOGIN}}
GIT_COMMITTER_EMAIL=${GH_LOGIN:-${LOGIN}}@bots.onym-n8n.local
MANAGER_SSH_PUBKEY=
ADMIN_SSH_PUBKEY=
MAC_HOST=host.docker.internal
MAC_HOST_USER=stellar-builder
MAC_HOST_PORT=22
ENV
        fi
        chmod 600 "${ENV_DIR}/${LOGIN}.env"
        echo "  seeded ${ENV_DIR}/${LOGIN}.env (fill in real tokens)" >&2
    fi
done <<<"$EMPLOYEES"

# Volumes section.
{
    echo "volumes:"
    while IFS= read -r LOGIN; do
        [ -z "$LOGIN" ] && continue
        echo "  ${LOGIN}-home:"
        echo "  ${LOGIN}-cache:"
    done <<<"$EMPLOYEES"
    echo
    cat <<'NETS'
networks:
  # employees-net is shared by manager-agent (defined in
  # the workstation compose file) and every employee. n8n is NOT on this
  # net — it reaches the manager over SSH from the other machine.
  employees-net:
    name: onym-n8n_employees-net
    driver: bridge
NETS
} >> "$OUT"

EMP_COUNT=$(printf '%s\n' "$EMPLOYEES" | grep -c '^.' || echo 0)
echo "==> wrote $OUT ($EMP_COUNT employees)"
